package com.aetherforge.api;import com.aetherforge.repo.QualityRepository;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.security.MessageDigest;import java.util.*;
@RestController @RequestMapping("/api/v1/quality") public class QualityController {private final QualityRepository repo;public QualityController(QualityRepository r){repo=r;}@GetMapping("/inspections") List<Map<String,Object>> list(){return repo.list();}@PostMapping(value="/inspect",consumes="multipart/form-data") Map<String,Object> inspect(@RequestPart MultipartFile image,@RequestParam(defaultValue="DEMO-PRODUCT") String productId)throws Exception{if(image.isEmpty()||image.getSize()>5_000_000||image.getContentType()==null||!image.getContentType().startsWith("image/"))throw new IllegalArgumentException("Upload a valid image under 5 MB");byte[] h=MessageDigest.getInstance("SHA-256").digest(image.getBytes());int score=h[0]&255;boolean pass=score%5!=0;String defect=pass?"":((h[1]&1)==0?"Scratch":"Misalignment");double conf=pass?.97:.91;repo.save(productId,pass?"PASS":"FAIL",conf,"DEMO INFERENCE","vision-demo-v1",image.getOriginalFilename(),defect);return Map.of("mode","DEMO INFERENCE","result",pass?"PASS":"FAIL","confidence",conf,"defect",defect.isBlank()?"None detected":defect,"modelVersion","vision-demo-v1");}}
